package cn.zhuatech.bpm.deep;
import jakarta.persistence.*;import java.time.*;
@Entity @Table(name="deep_bpm_definition",uniqueConstraints=@UniqueConstraint(columnNames={"process_key","version_no"})) class WorkflowDefinition{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@Column(name="process_key",nullable=false)String processKey;@Column(name="version_no",nullable=false)int versionNo;String name;String status="DRAFT";LocalDateTime createdAt=LocalDateTime.now();@Version long lockVersion;protected WorkflowDefinition(){}WorkflowDefinition(String k,int v,String n){processKey=k;versionNo=v;name=n;}}
@Entity @Table(name="deep_bpm_node",uniqueConstraints=@UniqueConstraint(columnNames={"definition_id","sequence_no"})) class WorkflowNode{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@Column(name="definition_id")Long definitionId;String nodeCode;@Column(name="sequence_no")int sequenceNo;String approverRole;int slaHours;protected WorkflowNode(){}WorkflowNode(Long d,String c,int s,String r,int h){definitionId=d;nodeCode=c;sequenceNo=s;approverRole=r;slaHours=h;}}
@Entity @Table(name="deep_bpm_instance",uniqueConstraints=@UniqueConstraint(columnNames="instance_no")) class WorkflowInstance{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@Column(name="instance_no")String instanceNo;Long definitionId;String initiator;String businessKey;String status="RUNNING";int currentSequence;LocalDateTime createdAt=LocalDateTime.now();LocalDateTime endedAt;@Version long lockVersion;protected WorkflowInstance(){}WorkflowInstance(String n,Long d,String i,String b,int s){instanceNo=n;definitionId=d;initiator=i;businessKey=b;currentSequence=s;}}
@Entity @Table(name="deep_bpm_task",uniqueConstraints=@UniqueConstraint(columnNames="task_no")) class WorkflowTask{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)Long id;Long instanceId;Long nodeId;@Column(name="task_no")String taskNo;String assignee;String status="READY";LocalDateTime dueAt;String decision;String comment;boolean escalated;@Version long lockVersion;protected WorkflowTask(){}WorkflowTask(Long i,WorkflowNode n,String no){instanceId=i;nodeId=n.id;taskNo=no;dueAt=LocalDateTime.now().plusHours(n.slaHours);}}
@Entity @Table(name="deep_bpm_event") class WorkflowEvent{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)Long id;String action;String aggregateNo;String detail;LocalDateTime createdAt=LocalDateTime.now();protected WorkflowEvent(){}WorkflowEvent(String a,String n,String d){action=a;aggregateNo=n;detail=d;}}
